145	     */
146	    public function getAllowedAmountToDep(float $amount, int $maxStep = 10): float
147	    {
148	        if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . " [" . __LINE__ . "]:" . json_encode(['maxStep' => $maxStep, 'amount' => $amount]));
149	        if ($maxStep < 0) return $this->_getAllowedAmountToDep($amount);
150	        $mutex = new RedisMutex(['redis' => Yii::$app->redis, 'expireTime' => 2]);
151	        $key = __METHOD__ . $this->id;
152	        try {
153	            if ($mutex->acquire($key)) {
154	                $value = $this->_getAllowedAmountToDep($amount);
155	                $mutex->release($key);
156	                return $value;
157	            }
158	        } catch (\Throwable $e) {
159	            $mutex->release($key);
160	        }
161	
162	        usleep(1_000_000 * 0.1);
163	        return $this->getAllowedAmountToDep($amount, --$maxStep);
164	    }
165	    private function _getAllowedAmountToDep(float $amount): float
166	    {
167	        $this->refresh();
168	        if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . " [" . __LINE__ . "]:" . json_encode(['left_until_max_amount' => $this->left_until_max_amount, 'amount' => $amount]));
169	        if (bccomp($this->left_until_max_amount, 0, 3) === 0) {
170	            return 0;
171	        } //если лимит исчерпан, то больше не зачисляем
172	
173	        if ($this->left_until_max_amount > $amount) { // если лимит позволяет
174	            $this->updateLeftUntilMaxAmount($amount);
175	            return $amount;
176	        }
177	
178	        $amount = $this->left_until_max_amount;
179	        $this->updateLeftUntilMaxAmount($amount);
180	        $this->left_until_max_amount = 0;
181	        return $amount;
182	    }
