196	    public static function hasMaxWin(int $userId, ?int $userBonusId = null, ?int $freespinId = null): bool
197	    {
198	        $where = array_filter([
199	            'user_id' => $userId,
200	            'active' => true,
201	            'finish' => false,
202	            'user_bonus_id' => $userBonusId,
203	            'freespin_id' => $freespinId,
204	        ], static fn($v) => $v !== null);
205	
206	        $ttl = ArrayHelper::getValue(Yii::$app->params, 'max_win.ttl', 6400);
207	        $key = self::makeKey($where, 'hasMaxWin');
208	
209	        $cached = Yii::$app->redis->get($key);
210	        if ($cached !== false && $cached !== null) {
211	            return $cached === '1';
212	        }
213	
214	        $exists = static::find()->where($where)->exists();
215	        Yii::$app->redis->setex($key, $ttl, (int)$exists);
216	
217	        return $exists;
218	    }
