        }

        if($game_action['type'] === 'freespin'){
            if (!isset($game_action['freespin_id'])){
                Logger::writeInfo('processingGameTransaction freespin_id empty: SessionId:'.$game_action['session_id']);
                return false;
            }

            /** @var Freespin $freespin */
            $freespin = Freespin::find()->where(['freespin_id' => $game_action['freespin_id']])->one();
            if (!$freespin) {
                Logger::writeInfo('processingGameTransaction Freespin not found: SessionId:'.$game_action['session_id']);
                return false;
            }
            /** @var UserBonus $userBonus */
            $userBonus = $freespin->userBonus;

            if (!$userBonus) {
                if ($freespin->hasMaxWin()) {
                    self::updateMaxWin($freespin);
                    $transaction = Yii::$app->db->beginTransaction();
                    $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$game_action['currency']])->one();
                    try {
                        $amount = $game_action['amount'];
                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                        $amount = $freespin->maxWinUserBonus->getAllowedAmountToDep($amount);
                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                        $wallet->deposit($amount);
                        $transaction->commit();
                    } catch (Exception $ex) {
                        $transaction->rollBack();
                        Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
                        throw $ex;
                    }
                }
                //якщо нема бонусу , то це може бути промокод просто з фс, без вейджеру - вони в іншій таблиці зберігаються
                $promocod = $freespin->bonusCodLog;
                if ($promocod && ($freespin->isEnded())) {
                    $promocod->used = true;
                    $promocod->save();
