                    exit();

                }
                if ($userBonus && !$userBonus->is_wager && $userBonus->hasMaxWin()) {
                    $amount = (float)$game_action['amount'];
                    $balanceBefore = (float)$game_action['balance_before'];
                    if ($userBonus->maxWinLeftUntilMaxAmount > $amount) {
                        $userBonus->maxWinLeftUntilMaxAmount = $userBonus->maxWinLeftUntilMaxAmount - $amount;
                    } else {
                        $amount = $userBonus->maxWinLeftUntilMaxAmount;
                        $userBonus->maxWinLeftUntilMaxAmount = 0;
                    }
                    $virtualBalance = $balanceBefore + $amount;
                    $game_action['balance_after'] = $virtualBalance;

                    GameTransaction::saveNewGameTransaction($game_action);
                    BackgroundGameProcess::runQueue($game_action, $user);

                    $data_responce = [
                        'balance' => $virtualBalance,
                        'transaction_id' => $transaction_id,
                    ];
                    header("Content-Type: application/json");
                    echo json_encode($data_responce);
                    Logger::checkTimeScriptLog($start, $hostname.' | '.$action.' | sid: '.$session_id);
                    if($debug){
                        $hostname .= '| test_collbk win_fs2 duration: '.round(microtime(true) - $start, 4).' sec; ';
                        $hostname .= '| Callback start_time: '.$start.'; end_time:'.microtime(true).' | DATA: '.VarDumper::dumpAsString(Yii::$app->request->post(), 30, false);
                        DetailedLog::log($user->id, DetailedLog::CATEGORY_GAME_TRANSACTION,'callback', $hostname);
                    }
                    exit();
                }
                $userBonusCod = $freespin->userBonusCod;
                if ($userBonusCod && ($freespin->quantity_left === '0' || $freespin->quantity_left === 0)) {
                    $userBonusCod->closeBonus();
                }
                if (!$userBonus && $freespin->hasMaxWin()) {
                    $amount = (float)$game_action['amount'];
                    $balanceBefore = (float)$game_action['balance_before'];
                    if ($freespin->maxWinLeftUntilMaxAmount > $amount) {
                        $freespin->maxWinLeftUntilMaxAmount = $freespin->maxWinLeftUntilMaxAmount - $amount;
                    } else {
                        $amount = $freespin->maxWinLeftUntilMaxAmount;
                        $freespin->maxWinLeftUntilMaxAmount = 0;
                    }
                    $virtualBalance = $balanceBefore + $amount;
                    $game_action['balance_after'] = $virtualBalance;
                    GameTransaction::saveNewGameTransaction($game_action);
                    BackgroundGameProcess::runQueue($game_action, $user);
                    $data_responce = [
                        'balance' => $virtualBalance,
                        'transaction_id' => $transaction_id,
                    ];
                    header("Content-Type: application/json");
                    echo json_encode($data_responce);
                    Logger::checkTimeScriptLog($start, $hostname.' | '.$action.' | sid: '.$session_id);
                    if($debug){
                        $hostname .= '| test_collbk win_fs2 duration: '.round(microtime(true) - $start, 4).' sec; ';
                        $hostname .= '| Callback start_time: '.$start.'; end_time:'.microtime(true).' | DATA: '.VarDumper::dumpAsString(Yii::$app->request->post(), 30, false);
                        DetailedLog::log($user->id, DetailedLog::CATEGORY_GAME_TRANSACTION,'callback', $hostname);
                    }
                    exit();
                }
            }
        }

        if($game_action['amount'] > 0){
            Yii::$app->db->createCommand(
                'UPDATE wallet SET amount = amount + :amount WHERE id = :id',
                [':amount' => $game_action['amount'], ':id' => $wallet->id]
            )->execute();
            $wallet->amount = $wallet->amount + $game_action['amount'];
        }

        $game_action['balance_after'] = floatval($wallet->amount);
        GameTransaction::saveNewGameTransaction($game_action);

        try {
            if($game_action['type'] == 'win' && $game_action['amount'] > 0){
                if($selfLimitation = SelfLimitation::findOne(['user_id' => $user->id])){
                    $selfLimitation->checkPrepareProfitTransaction('win',$game_action['amount'],$beforeAmount);
                    if(!$selfLimitation->selfLimitationData->save(false)){
                        Logger::writeInfo('Error_save_selfLimitationData in win transactionId '.$transaction_id.' err: '.VarDumper::dumpAsString($selfLimitation->selfLimitationData->getErrors()));
                    }
                }
            }
        } catch (\Throwable $ex) {
            Logger::writeInfo('catch_selfLimitation in win transactionId '.$transaction_id.' err: '.$ex->getMessage());
        }


    } else {
        Logger::writeInfo('TransactionID EXIST!!! '.$transaction_id.' userId:'.$user->id);
        $game_action['balance_after'] = floatval($game_action['balance_before']);

        $data_responce = [
            'balance' => $game_action['balance_after'],
            'transaction_id' => $transaction_id,
        ];
        header("Content-Type: application/json");
        echo json_encode($data_responce);
        Logger::checkTimeScriptLog($start, $hostname.' | '.$action.' | sid: '.$session_id);
        if($debug){
            $hostname .= '| test_collbk win_isset_tr duration: '.round(microtime(true) - $start, 4).' sec; ';
            $hostname .= '| Callback start_time: '.$start.'; end_time:'.microtime(true).' | DATA: '.VarDumper::dumpAsString(Yii::$app->request->post(), 30, false);
            DetailedLog::log($user->id, DetailedLog::CATEGORY_GAME_TRANSACTION,'callback', $hostname);
        }
        exit();

    }

    //if win == 0 не відправляємо в чергу
    if($game_action['amount'] > 0 || $game_action['type'] == 'freespin'){
        try {
            if (in_array('*',Yii::$app->params['users_for_go_worker']) || in_array($user->id,Yii::$app->params['users_for_go_worker'])) {
                Yii::$app->queueGameGo->push(new \common\jobs\GameProcess(['game_action' => $game_action]));
            }else{
                Yii::$app->queueGame->push(new \common\jobs\GameProcess(['game_action' => $game_action]));
            }
        } catch (\Exception $ex) {
            BackgroundGameProcess::processingGameTransaction($game_action);
        }
    }

