6	
7	/**
8	 * Зачислять ли сумму бонуса без вейджера по окончании его ФС — чистое ядро для `BackgroundGameProcess`.
9	 *
10	 * Активация бонуса без вейджера сама зачисляет сумму и ставит `accrual_time` (лестница —
11	 * DBR-009, DBR-011; прежний путь «Фриспинов» — так же). Если зачисление уже было, по окончании
12	 * ФС бонус только закрывается: иначе сумма попала бы на баланс второй раз.
13	 */
14	final class FreespinEndCredit
15	{
16	    public static function isDue(mixed $amount, mixed $accrualTime): bool
17	    {
18	        return $amount > 0 && empty($accrualTime);
19	    }
20	}
