1	<?php
2	
3	namespace common\services;
4	
5	use common\models\Freespin;
6	
7	/**
8	 * Синхронне оновлення прогресу фріспіна (quantity_left / status / total_win),
9	 * яке робиться у callback ДО передачі виграшу в асинхронний конвеєр
10	 * (BackgroundGameProcess). Спільне для провайдерів (EGT зараз; Gaminator — у SiteController).
11	 *
12	 * Гарантії:
13	 *  - quantity_left не «росте» назад при out-of-order/replay callback;
14	 *  - статус END не скидається назад у USED.
15	 */
16	final class FreespinProgressService
17	{
18	    /**
19	     * Оновити прогрес після спіну.
20	     *
21	     * @param Freespin   $freespin
22	     * @param int|null   $remaining  залишок спінів (EGT: giftSpin.remaining). null — не чіпати quantity_left
23	     * @param float      $winAmount  виграш у мажорних одиницях (додається до total_win), 0 для програшного спіну
24	     */
25	    public static function recordSpinProgress(Freespin $freespin, ?int $remaining, float $winAmount = 0.0): void
26	    {
27	        if ($remaining !== null) {
28	            $current = $freespin->quantity_left === null ? PHP_INT_MAX : (int)$freespin->quantity_left;
29	            // не дозволяємо залишку збільшуватись (захист від out-of-order/replay)
30	            if ($remaining <= $current) {
31	                $freespin->quantity_left = $remaining;
32	            }
33	
