if($bonusCod->isFreeSpin()){
    $game = $bonusCod->getGame();
    if(Freespin::canCreateMoreSimilar($game->slug, $user->uid)){

        if ($bid = $user->getWagerActiveBonusId()) {
            $wagerUserBonusPre = UserBonus::findOne($bid);
            if ($wagerUserBonusPre && $wagerUserBonusPre->freespin_id) {
                $freespinOldPre = Freespin::find()->where(['freespin_id' => $wagerUserBonusPre->freespin_id])->one();
                if ($freespinOldPre && $freespinOldPre->status == Freespin::STATUS_USED && $freespinOldPre->valid_until > time()) {
                    $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'cannot_cancel_fs_after_start')]);
                    return ['success' => false, 'html' => $html];
                }
            }
        }
        $mutex = new RedisMutex(['redis' => Yii::$app->redis, 'expireTime' => 60]);// Expire time, in seconds
        $mutexName = 'activate_freespin_'.$user->id;
        if (!$mutex->acquire($mutexName)) {
            $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'limit_attempts_Try_later')]);
            return ['success' => false, 'html' =>$html];
        }
        $freespinId = Freespin::createFreeSpin(
            userUuid: Yii::$app->user->identity->uid,
            currency: $bonusCod->currency,
            gameUid: $game->slug,
            denomination: $bonusCod->freespin_setting['denominations'],
            bet: $bonusCod->freespin_setting['betId'],
            quantity: $bonusCod->freespin_setting['countFs'],
            bonusId: $bonusCod->id,
            bonus_type: Freespin::BONUS_COD
        );
        if (!$freespinId) {
            $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'error_create_bonus')]);
            return ['success' => false, 'html' => $html];
        }
        $freespin = Freespin::find()->where(['freespin_id'=>$freespinId])->one();
        $userBonus->freespin_id = $freespinId;
        $userBonus->to = $freespin->valid_until;
    }else{

        $textFsId = '';
        try {
            $freespin = Freespin::find()
                ->where(['game_uuid' => $game->slug, 'player_id' => $user->uid])
                ->andWhere(['>', 'valid_until', time()])
                ->andWhere(['in', 'status', [Freespin::STATUS_READY, Freespin::STATUS_USED]])
                ->orderBy('id DESC')
                ->one();
            if ($freespin) {
                $textFsId = ' (fsId:' . $freespin->id.')';
            }

        } catch (Exception $e) {

