1	<?php
2	
3	namespace common\services\bonus\reward;
4	
5	use common\models\Freespin;
6	
7	/**
8	 * Боевой шлюз {@see RewardIssueService} для одного выданного бонуса: ФС — через
9	 * `Freespin::createFreeSpin` и отмену у провайдера, зачисление — транзакцией, которую
10	 * передаёт контроллер активации (design, решение 4: маршрутизация и ответ — свои у сайта и API).
11	 *
12	 * @infection-ignore-all тонкий адаптер к провайдеру ФС и БД без собственных правил, в common/unit их нет
13	 * @codeCoverageIgnore
14	 */
15	final class FreespinRewardIssueGateway implements RewardIssueGateway
16	{
17	    /**
18	     * @param \Closure(DepositReward, ?string): void $credit транзакция зачисления; при ошибке откатывается и бросает
19	     */
20	    public function __construct(
21	        private readonly string $playerUid,
22	        private readonly string $currency,
23	        private readonly string $gameSlug,
24	        private readonly mixed $denomination,
25	        private readonly mixed $betId,
26	        private readonly int $bonusId,
27	        private readonly string $event,
28	        private readonly \Closure $credit,
29	    ) {
30	    }
31	
32	    public function createFreespins(int $count): ?string
33	    {
34	        $freespinId = Freespin::createFreeSpin(
35	            $this->playerUid,
36	            $this->currency,
37	            $this->gameSlug,
38	            $this->denomination,
39	            $this->betId,
40	            $count,
41	            $this->bonusId,
42	            $this->event
43	        );
44	        // createFreeSpin отвечает false при отказе провайдера или лимита
45	        return $freespinId ? (string)$freespinId : null;
46	    }
47	
48	    /**
49	     * Как откат в текущей активации: отмена у провайдера и статус «отменено автоматически».
50	     */
51	    public function cancelFreespins(string $freespinId): bool
52	    {
53	        $freespin = Freespin::find()->where(['freespin_id' => $freespinId])->one();
54	        if ($freespin === null || !Freespin::cancelByProvider($freespin)) {
55	            return false;
56	        }
57	        $freespin->status = Freespin::STATUS_CANCEL_AUTO;
58	        $freespin->is_canceled = time();
59	        return $freespin->save(false);
60	    }
61	
62	    public function credit(DepositReward $reward, ?string $freespinId): void
63	    {
64	        ($this->credit)($reward, $freespinId);
65	    }
66	}
