public function getMaxWin(): float|null
{
    return $this->maxWinSettingBonus?->value;
}

public function setMaxWin(?float $value): void
{
    if (!$this->maxWinSettingBonus && $value !== null) {
        MaxWinSettingBonus::create(value: $value, bonusId: $this->id);
        $this->refresh();
        return;
    }

    if ($this->maxWinSettingBonus && $value === null) {
        $this->maxWinSettingBonus->delete();
        $this->refresh();
        return;
    }

    if ($value !== null && $this->maxWinSettingBonus !== null) {
        $this->maxWinSettingBonus->value = $value;
        $this->maxWinSettingBonus->save();
        return;
    }
}

