 * Record freespin progress (quantity_left/status, and total_win for a win) for a
 * gift-spin bet/win. No balance change here.
 */
private function recordGiftSpinProgress(array $data, User $user, ?string $currency, float $winAmount): void
{
    $freespin = $this->findGiftSpin($data, $user, $currency);
    if (!$freespin) {
        return;
    }
    FreespinProgressService::recordSpinProgress($freespin, $this->giftSpinRemaining($data), $winAmount);
}

/**
 * §4.7 Gift Spin win. Mirrors the Gaminator freespin-win money flow
 * (SiteController) for full parity:
 *  - plain freespin (no bonus, no max-win) → credit the real wallet now;
 *  - wager / max-win bonus → DO NOT credit the real wallet here; the win is
 *    reported to EGT as bonusAmount and the shared async pipeline
 *    (BackgroundGameProcess) accrues wager / deposits the capped amount /
 *    closes the bonus — identically to Gaminator.
 * Freespin progress (quantity_left/status/total_win) is updated even for a
 * losing spin (amount = 0). Idempotency is guaranteed by the caller running
 * this only on the genuine credit path (transferId not yet processed).
 *
 * @return array|null signed response, or null to fall through to the normal
 *                    win credit (freespin not found / mismatch)
 */
private function processGiftSpinWin(
    array $data,
    User $user,
    Wallet $wallet,
    string $transferId,
    string $roundNumber,
    $gameKey,
    string $sessionId,
    float $beforeAmount,
    int $rawAmountCoins,
    float $amount,
    int $time
): ?array {
    $freespin = $this->findGiftSpin($data, $user, $wallet->currency);
    if (!$freespin) {
        return null; // anomalous GIFT_SPIN — let the normal win path credit + log
    }

    // 1) progress (quantity_left / status / total_win), even for a losing spin
    FreespinProgressService::recordSpinProgress($freespin, $this->giftSpinRemaining($data), $amount);

    // Close a linked bonus-code campaign when spins are exhausted — parity with
    // SiteController's sync `userBonusCod->closeBonus()` (the async pipeline only
    // flags BonusCodLog.used).
    $userBonusCod = $freespin->userBonusCod;
    if ($userBonusCod && (int)$freespin->quantity_left === 0) {
        $userBonusCod->closeBonus();
    }

    // 2) credit routing — same predicate as SiteController's freespin-win branch.
    // The real/bonus split is computed by EgtWallet::giftSpinSplit and shared
    // with the idempotency replay so a retry reproduces the identical response.
    $creditRealSync = $this->giftSpinCreditsReal($freespin);
    $split = EgtWallet::giftSpinSplit($creditRealSync, $rawAmountCoins);

    if ($creditRealSync && $amount > 0) {
        Yii::$app->db->createCommand(
            'UPDATE wallet SET amount = amount + :amount WHERE id = :id',
            [':amount' => $amount, ':id' => $wallet->id]
        )->execute();
        $wallet->amount = $wallet->amount + $amount;
    }

    // 3) ledger record (idempotency key = transferId) tagged as a freespin win
    $game_action = [
        'player_id'          => $user->uid,
        'user_id'            => $user->id,
        'currency'           => $wallet->currency,
        'action'             => 'win',
        'amount'             => $amount,
        'transaction_id'     => $transferId,
        'bet_transaction_id' => $roundNumber,
        'game_uuid'          => $gameKey,
        'session_id'         => $sessionId,
        'type'               => 'freespin',
        'freespin_id'        => $freespin->freespin_id,
        'balance_before'     => $beforeAmount,
        'balance_after'      => $wallet->amount,
        'time'               => $time,
    ];
    GameTransaction::saveNewGameTransaction($game_action);

    // 4) shared async pipeline: wager accrual / max-win capped deposit / bonus close
    //    (the same code path Gaminator freespin wins use)
    BackgroundGameProcess::runQueue($game_action, $user);

    // Win not credited to the real account is reported to EGT as bonus money (§4.7).
    return $this->signedTransferResponse($wallet, $transferId, $split['real'], $split['bonus']);
}

/**
 * Whether a gift-spin win is credited to the REAL balance synchronously (plain
 * freespin) vs routed to bonus money (wager / max-win) — the SiteController
 * freespin-win predicate. Deterministic from the freespin's bonus config, so
 * the idempotency replay reconstructs the same real/bonus split.
 */
private function giftSpinCreditsReal(Freespin $freespin): bool
{
    $userBonus = $freespin->userBonus;
    $hasMaxWin = ($userBonus && $userBonus->hasMaxWin()) || (!$userBonus && $freespin->hasMaxWin());
    $isWager   = $userBonus && $userBonus->is_wager;

    return !($isWager || $hasMaxWin);
}

